mapper.select:
SELECT c.id, c.conversation_uid, c.user_id, c.project_id, c.title, c.summary,
       c.pinned, c.archived_at, c.deleted_at, c.created_at, c.updated_at
FROM writing_document_conversation_link l
INNER JOIN assistant_conversation c ON c.conversation_uid = l.conversation_uid
WHERE l.user_id = #{userId}
  AND l.document_id = #{documentId}
  AND c.user_id = #{userId}
  AND c.deleted_at IS NULL
ORDER BY c.updated_at ASC, c.id ASC

SELECT DISTINCT c.id, c.conversation_uid, c.user_id, c.project_id, c.title, c.summary, c.pinned, c.archived_at, c.deleted_at, c.created_at, c.updated_at FROM assistant_conversation c INNER JOIN assistant_message m ON m.conversation_uid = c.conversation_uid WHERE c.user_id = #{userId} AND c.deleted_at IS NULL AND m.user_id = #{userId} AND m.role = 'user' AND m.content LIKE '%[写作教练 Copilot 请求]%' AND (
m.content LIKE CONCAT('%', #{probe}, '%')
) ORDER BY c.updated_at ASC, c.id ASC LIMIT 20
